import React, { useState, useEffect } from 'react';
import Header from './Header';
import Footer from './Footer';
import Signin from './Signin';
import User from './User';
import Admin from './Admin';

export default function App() {
  // Read current active session from localStorage if available
  const [currentUser, setCurrentUser] = useState(() => {
    const saved = localStorage.getItem('currentUser');
    return saved ? JSON.parse(saved) : null;
  });

  const [activeTab, setActiveTab] = useState('home');

  // Handle successful signin / registration
  const handleLoginSuccess = (userData) => {
    setCurrentUser(userData);
    localStorage.setItem('currentUser', JSON.stringify(userData));
    setActiveTab('home');
  };

  // Handle logout
  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('currentUser');
    setActiveTab('home');
  };

  // If no user is logged in, show authentication screen
  if (!currentUser) {
    return <Signin onLoginSuccess={handleLoginSuccess} />;
  }

  return (
    <div style={styles.appWrapper}>
      <Header 
        user={currentUser} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={handleLogout} 
      />

      <main style={styles.mainContent}>
        {currentUser.role === 'admin' ? (
          <Admin user={currentUser} activeTab={activeTab} />
        ) : (
          <User user={currentUser} activeTab={activeTab} />
        )}
      </main>

      <Footer setActiveTab={setActiveTab} />
    </div>
  );
}

const styles = {
  appWrapper: {
    display: 'flex',
    flexDirection: 'column',
    minHeight: '100vh',
    backgroundColor: '#18181b',
    color: '#ffffff',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  mainContent: {
    flex: 1,
    padding: '32px 24px',
    maxWidth: '1200px',
    width: '100%',
    margin: '0 auto',
    boxSizing: 'border-box',
  },
};
